head.script:
scwin.gDepCd = js_dep_cd;
scwin.gLdMktTp = js_market;
scwin.gParamObj;
scwin.getPar, scwin.fn_SetPar;
scwin.strDepCd = js_dep_cd.substring(0, 2);

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.hideDebugCtrls();
        $c.cm.PanelToGroupBox(panel_1);
        scwin.resizeToWin();
        scwin.moveWin();
        await scwin.init();
        await scwin.getParam();
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30001.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    const sbmOptions = {
        id : "sbm_dts_Status",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Status=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    rdo_Market_Flag.setValue(scwin.gLdMktTp);
    // 코스닥만 SMS 기능 보이게
    label_3.hide();
    cmb_SMS.hide();

    // 코스닥 시장운영팀은 '확인여부'가 불필요하다.
    if (scwin.gDepCd === '3220') {
        label_1.hide();
        cmb_Confirm.hide();
    } else if (js_market === "1") {
        // 유가시장은 안보여야 함
        label_1.style.display = "none"; // 담당자확인여부
        cmb_Confirm.style.display = "none"; // 담당자확인여부

    } else if (js_market === "2") {
        label_3.show("");
        cmb_SMS.show("");
    } else if (js_market === "3") {
        // 파생은 안보여야 함_LSH
        label_1.style.display = "none"; // 담당자확인여부
        cmb_Confirm.style.display = "none"; // 담당자확인여부

    }
    if (scwin.gDepCd === "11D0") {
        label_12.hide();
        label_digital.show("");
        panel_chrg.hide();
    } else {
        label_12.show("");
        label_digital.hide();
        panel_chrg.show("");
    }
    // 2014.02.09 유가 공시서비스팀 추가
    // 2650 추가 2021.02.22
    // 2660 추가 2021.03.12
    // strDepCd 로 변경 2021.05.28
    // if((js_dep_cd == '2620' || js_dep_cd == '2630' || js_dep_cd == '2611' || js_dep_cd == '2650' || js_dep_cd == '2660')) {
    if (scwin.strDepCd === '26') {
        txb_DISCLS_SCHDL_GRD_CD.show(""); // 등급
        label_2.show("");
    } else {
        txb_DISCLS_SCHDL_GRD_CD.hide(); // 등급
        label_2.hide(); // 등급

    }

    // showObj(panel_chrg, false);

};

