/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert(trs_Save);
        dts_Schedule.Reset();
        dts_Schedule.insertRow(); // 성공일 때 Default로 한줄 추가해 놓는다.
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30001.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));
        const fr_fn_SearchMain = $c.frame.path("../").fn_SearchMain;
        const isFnSrch = $c.stf.getQuery(frame.srcUrl, "isFnSrch"); // 저장완료 후 조회method 실행여부 파라미터값 저장

        /*기타시장안내서식 && 코스닥공시팀일 경우 '공시일정입력폼' 화면(STF30001)으로 이동하며
        // 이럴경우 'isFnSrch' 변수값을 파라미터로 넘겨줌
        // 해당 경우에만 첫번째 if문을 수행하며, 나머지 분기문은 기존 소스를 유지함 by LDJ_20120920 */
        if (isFnSrch === 'N') {
            await $c.win.closePopup();
        } else if (fr_fn_SearchMain === undefined) {
            let parentWin = $c.frame.path("../");
            const parendID = $c.stf.getQuery(frame.srcUrl, "frameid");
            const fr_fn_Search = $c.frame.path(parendID).fn_Search;
            fr_fn_Search();
            await $c.win.closePopup();
        } else {
            fr_fn_SearchMain();
            await $c.win.closePopup();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30001.trs_Save_OnSuccess" });
    }
};

