/**
 * @method
 * @name dts_Schedule_OnLoadCompleted
 * @description dts_Schedule 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Schedule_OnLoadCompleted = async function(rowcount) {
    try {
        let vISUR_CD = dts_Schedule.getCellData(1, "ISUR_CD");
        let vLD_MKT_TP_CD = dts_Schedule.getCellData(1, "LD_MKT_TP_CD");
        if (vISUR_CD !== '' && vISUR_CD.length === 5) {
            await scwin.readChrgInfo(vISUR_CD, vLD_MKT_TP_CD);
            // showObj(panel_chrg, true);

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30001.dts_Schedule_OnLoadCompleted" });
    }
};

