            // 디지털증권인 경우 상장신청인 팝업호출
            scwin.fn_SetPar = scwin.setParIsur2;
            await scwin.popFindDigitalIsurAll();
        } else {
            $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30001.btn_ISUR_CD_onclick" });
    }
};

