/**
 * @method
 * @name txa_Remk_onchange
 * @description txa_Remk 변경 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txa_Remk_onchange = function() {
    try {
        txb_title_size.setValue($c.stf.getStringSize(txa_Remk.getValue()));
        if ($c.stf.getStringSize(txa_Remk.getValue()) > 1500) {
            txb_alert.setValue('가 초과되었습니다.');
            txa_Remk.Focus();
            return;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30001.txa_Remk_onchange" });
    }
};

