        ref : "",
        target : "dts_Charge2_Info=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name readSchedule
 * @description read Schedule 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSchedule = async function() {
    url += "&DISCLS_SCHDL_ADM_DD=" + txb_DISCLS_SCHDL_ADM_DD.getValue();
    url += "&BYDD_SEQ=" + txb_BYDD_SEQ.getValue();
    url += "&INTEG_USR_ID=" + txb_INTEG_USR_ID.getValue(); // 통합사용자ID
    url += "&SCREN_ID=" + 'ULDSTF30001.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Schedule",
        action : "/DisclosureSchedule.do",
        ref : "",
        target : "dts_Schedule=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 2009.08.07 담당자확인여부추가
    if (js_market === "2" || js_market === "6") {
        // 코넥스 시장 추가
        cmb_Confirm.setValue(dts_Schedule.getCellData(1, "SCHDL_CONFRM_YN"));
    }
    if (js_market === "2") {
        cmb_SMS.setValue(dts_Schedule.getCellData(1, "SMS_TRNSM_YN"));
    }

    // setObjectValue(cmb_Status, dts_Schedule.NameString(1, "discls_schdl_act_stat_cd"));

};

/**
 * @method
 * @name setNewMode
 * @description row 추가.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setNewMode = async function() {
    // row 추가.
    // 헤더 꼭 가져와야되나.씨~~~
    const sbmOptions = {
        id : "sbm_dts_Schedule",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Schedule=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_Schedule.insertRow();
    txb_Cmd.setValue("C");
    txb_EMP_NO.setValue(js_emp_no);
    rdo_Market_Flag.setValue(scwin.gLdMktTp);
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (await scwin.checkForm()) {
        txb_EMP_NO.setValue(js_emp_no);
        let res = window.confirm("[저장]하시겠습니까?");
        if (res) {
            let vCMD = (txb_Cmd.getValue() === "C") ? "registerSchedule" : "modifySchedule";

            // 시장구분이 파생이고 등록이면 다른 메소드 사용_LSH
            if (scwin.gLdMktTp === "3" && vCMD === "registerSchedule") {
                vCMD = "registerScheduleDerivatives";
            }
            if (js_dep_cd === "11D0" && vCMD === "registerSchedule") {
                vCMD = "registerScheduleDigital";
            }
            // 2009.08.07 담당자확정여부추가
            if (js_market === "2" || js_market === "6") {
                // 코스닥            코넥스 추가 20130522 LDJ
                dts_Schedule.setCellData(1, "SCHDL_CONFRM_YN", cmb_Confirm.getValue());
            }

            // 2013.09.10 SMS 전송여부추가
            if (js_market === "2") {
                // 코스닥 추가 20130910 LDS362
                dts_Schedule.setCellData(1, "SMS_TRNSM_YN", cmb_SMS.getValue());

                // ********************************************************************
