/**
 * @method
 * @name getParam
 * @description opener로 부터 param을 받는다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getParam = async function() {
    // opener로 부터 param을 받는다.
    let parentWin = $c.frame.path("../");
    // alert(frame.srcUrl);
    const src = $c.stf.getQuery(frame.srcUrl, "src");
    if (src === "JSP") // JSP call

    {
        const cmd = $c.stf.getQuery(frame.srcUrl, "cmd");
        if (cmd === "C") {
            await scwin.setNewMode();
        } else {
            const vDiscls_schdl_adm_dd = $c.stf.getQuery(frame.srcUrl, "discls_schdl_adm_dd");
            const vBydd_seq = $c.stf.getQuery(frame.srcUrl, "bydd_seq");
            const vInteg_usr_id = $c.stf.getQuery(frame.srcUrl, "integ_usr_id");
            txb_Cmd.setValue(cmd);
            txb_DISCLS_SCHDL_ADM_DD.setValue(vDiscls_schdl_adm_dd);
            txb_BYDD_SEQ.setValue(vBydd_seq);
            txb_INTEG_USR_ID.setValue(vInteg_usr_id);
            btn_VIEWDSCL.show("");
            await scwin.readSchedule();
            btn_ISUR_CD.hide();
            btn_Delete.show("");
            txb_ISUR_CD.setReadOnly(true);
        }
    } else {
        const paramObj = parentWin.scwin.gParamObj;
        txb_Cmd.setValue(paramObj.param0);
        txb_DISCLS_SCHDL_ADM_DD.setValue(paramObj.param1);
        txb_BYDD_SEQ.setValue(paramObj.param2);
        txb_INTEG_USR_ID.setValue(paramObj.param3);
        // alert(paramObj.param0);
        if (paramObj.param0 === null || paramObj.param0 === undefined || paramObj.param0 === "" || paramObj.param0 === "C") {
            await scwin.setNewMode();
            btn_VIEWDSCL.hide();
        } else if (paramObj.param0 === "R") {
            await scwin.readSchedule();
            btn_ISUR_CD.hide();
            btn_Delete.show("");
            txb_ISUR_CD.setReadOnly(true);
        }
    }
    //    var paramObj = parentWin.gParamObj;

    //    if (paramObj == undefined) return;

};

/**
 * @method
 * @name setParam
 * @description child에 param을 넘긴다.
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function() {
    // child에 param을 넘긴다.
    const argv = scwin.setParam.arguments;
    const argc = scwin.setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (let i = 0; i < argc; i++) // actual arguments

    {
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};

/**
 * @method
 * @name checkForm
