 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    // alert(getObjectValue(rdo_Market_Flag)); ??
    if (rdo_Market_Flag.getValue() === "") {
        await $c.win.alert("[시장구분]을 선택하세요.");
        rdo_Market_Flag.focus();
        return false;
    }
    /*
	if (getObjectValue(txb_ISUR_CD) == "")
	{
		alert("[회사코드]을 선택하세요.");txb_ISUR_CD.focus();return false;
	}
     */
    if (js_sndloc === '13' && txb_COM_NM.getValue() === "") {
        await $c.win.alert("[회사코드]을 선택하세요.");
        txb_COM_NM.focus();
        return false;
    }
    if (edt_Deadline.getValue() === "") {
        await $c.win.alert("[관리기한]을 선택하세요.");
        edt_Deadline.focus();
        return false;
    }
    if (txb_SCHDL_ADM_ITM_TP_NM.getValue() === "") {
        await $c.win.alert("[관리항목]을 선택하세요.");
        txb_SCHDL_ADM_ITM_TP_NM.focus();
        return false;
    }
    /*
    if (getObjectValue(txb_DISCLS_SCHDL_ADM_CONTN) == "")
    {
    	alert("[관리항목]을 선택하세요.");txb_DISCLS_SCHDL_ADM_CONTN.focus();return false;
    }
    if (getObjectValue(txb_ACPT_NO) == "")
    {
    	alert("[일정추출공시]을 선택하세요.");txb_ACPT_NO.focus();return false;
    }
    if (getObjectValue(txb_RptNm) == "")
    {
    	alert("[일정추출공시]을 선택하세요.");txb_RptNm.focus();return false;
    }
    if (getObjectValue(edt_DISCLS_PUBL_DDTM) == "")
    {
    	alert("[공시일]을 선택하세요.");edt_DISCLS_PUBL_DDTM.focus();return false;
    }
     */
    if (cmb_Status.getValue() === "") {
        await $c.win.alert("[일정상태]을 선택하세요.");
        cmb_Status.focus();
        return false;
    }
    if (txa_Remk.getValue() === "") {
        await $c.win.alert("[비고]을 입력하세요.");
        txa_Remk.focus();
        return false;
    }

    // 2009.08.07 일정확정여부추가
    if (js_market === "2" && scwin.gDepCd !== '3220' || js_market === "6") {
        // 코스닥공시총괄팀만 해당/시장운영팀은 제외.코넥스 추가 20130522 LDJ
        if (cmb_Confirm.getValue() === "") {
            await $c.win.alert("[확정여부]를 선택하세요.");
            cmb_Confirm.focus();
            return false;
        }
    }
    // 2013.09.10 SMS전송여부추가
    if (js_market === "2") {
        // 코스닥 추가 20130910 LDS362
        if (scwin.gDepCd !== '3220' && cmb_SMS.getValue() === "") {
            // 코스닥 시장운영팀은 SMS 체크 제외 by LDJ_20130917
            await $c.win.alert("SMS 전송여부를 선택하세요.");
            cmb_SMS.focus();
            return false;
        }
    }
    if ($c.stf.checkMaxLength(txa_Remk, 1500, "비고")) {
        return true;
    }
};

